/// Items control through the same candidate boundary used by other application entries.
pub fn items(
    state: &InventoryInteractionState,
    frame: u32,
    registers: &ItemsRegisters,
    limits: crate::recovered_application_control::ApplicationControlLimits,
    services: &mut impl crate::recovered_application_control::ApplicationControlServices,
) -> Result<crate::recovered_application_control::ApplicationControlPlan, RuleError> {
    use crate::recovered_application_control::{
        self as application, ApplicationRegisters, RegisterBits,
    };
    let input = ApplicationRegisters {
        data: std::array::from_fn(|n| RegisterBits {
            value: registers.data[n],
            known_mask: registers.known_data_bits[n],
        }),
        address: std::array::from_fn(|n| {
            registers.address[n].map_or(RegisterBits::default(), RegisterBits::full)
        }),
        ccr: registers.condition_codes,
        ccr_known_mask: registers.known_condition_codes,
    };
    application::execute(state, 0x129516, frame, input, limits, services)
}
